sql:
CREATE TABLE s.ctaa_subpart (id int, region text, tenant int) PARTITION BY LIST (region);
CREATE TABLE s.ctaa_subpart_east PARTITION OF s.ctaa_subpart FOR VALUES IN ('east') PARTITION BY HASH (tenant);
CREATE TABLE s.ctaa_subpart_east_0 PARTITION OF s.ctaa_subpart_east FOR VALUES WITH (modulus 2, remainder 0)

CREATE TABLE s.ctaa_subpart2 (occurred date, region text) PARTITION BY RANGE (occurred);
CREATE TABLE s.ctaa_subpart2_2025 PARTITION OF s.ctaa_subpart2 FOR VALUES FROM ('2025-01-01') TO ('2026-01-01') PARTITION BY LIST (region);
CREATE TABLE s.ctaa_subpart2_2025_east PARTITION OF s.ctaa_subpart2_2025 FOR VALUES IN ('east')

CREATE TABLE s.ctaa_range_nulls (id int, v int) PARTITION BY RANGE (v);
CREATE TABLE s.ctaa_range_nulls_low PARTITION OF s.ctaa_range_nulls FOR VALUES FROM (MINVALUE) TO (0);
CREATE TABLE s.ctaa_range_nulls_high PARTITION OF s.ctaa_range_nulls FOR VALUES FROM (0) TO (MAXVALUE)

CREATE TABLE s.ctaa_list_multi (id int, a text, b text) PARTITION BY LIST (a);
CREATE TABLE s.ctaa_list_multi_p1 PARTITION OF s.ctaa_list_multi FOR VALUES IN ('x', 'y', 'z');
CREATE TABLE s.ctaa_list_multi_p2 PARTITION OF s.ctaa_list_multi FOR VALUES IN ('a', 'b', 'c')

CREATE TABLE s.ctaa_list_dup (id int, region text) PARTITION BY LIST (region);
CREATE TABLE s.ctaa_list_dup_p1 PARTITION OF s.ctaa_list_dup FOR VALUES IN ('east');
CREATE TABLE s.ctaa_list_dup_p2 PARTITION OF s.ctaa_list_dup FOR VALUES IN ('east')

CREATE TABLE s.ctaa_list_int (id int, code int) PARTITION BY LIST (code);
CREATE TABLE s.ctaa_list_int_p1 PARTITION OF s.ctaa_list_int FOR VALUES IN (1, 2, 3);
CREATE TABLE s.ctaa_list_int_p2 PARTITION OF s.ctaa_list_int FOR VALUES IN (4, 5, 6)

CREATE TABLE s.ctaa_hash_text (id int, tag text) PARTITION BY HASH (tag);
CREATE TABLE s.ctaa_hash_text_0 PARTITION OF s.ctaa_hash_text FOR VALUES WITH (modulus 3, remainder 0);
CREATE TABLE s.ctaa_hash_text_1 PARTITION OF s.ctaa_hash_text FOR VALUES WITH (modulus 3, remainder 1);
CREATE TABLE s.ctaa_hash_text_2 PARTITION OF s.ctaa_hash_text FOR VALUES WITH (modulus 3, remainder 2)

CREATE TABLE s.ctaa_range_int (id int, n int) PARTITION BY RANGE (n);
CREATE TABLE s.ctaa_range_int_neg PARTITION OF s.ctaa_range_int FOR VALUES FROM (-1000) TO (0);
CREATE TABLE s.ctaa_range_int_pos PARTITION OF s.ctaa_range_int FOR VALUES FROM (0) TO (1000)

CREATE TABLE s.ctaa_hash_bigint (id bigint, tenant bigint) PARTITION BY HASH (tenant);
CREATE TABLE s.ctaa_hash_bigint_0 PARTITION OF s.ctaa_hash_bigint FOR VALUES WITH (modulus 2, remainder 0);
CREATE TABLE s.ctaa_hash_bigint_1 PARTITION OF s.ctaa_hash_bigint FOR VALUES WITH (modulus 2, remainder 1)

CREATE TABLE s.ctaa_list_default2 (code text) PARTITION BY LIST (code);
CREATE TABLE s.ctaa_list_p1 PARTITION OF s.ctaa_list_default2 FOR VALUES IN ('a');
CREATE TABLE s.ctaa_list_default2_def PARTITION OF s.ctaa_list_default2 DEFAULT;
CREATE TABLE s.ctaa_list_default2_def2 PARTITION OF s.ctaa_list_default2 DEFAULT

CREATE TABLE s.ctaa_list_bool (active boolean) PARTITION BY LIST (active);
CREATE TABLE s.ctaa_list_bool_t PARTITION OF s.ctaa_list_bool FOR VALUES IN (true);
CREATE TABLE s.ctaa_list_bool_f PARTITION OF s.ctaa_list_bool FOR VALUES IN (false)

CREATE TABLE s.ctaa_temp_on_commit_del (id int);
CREATE TEMP TABLE ctaa_temp_del_rows (id int) ON COMMIT DELETE ROWS;
INSERT INTO ctaa_temp_del_rows VALUES (1),(2)

CREATE TABLE s.ctaa_range_part_def (id int, v int) PARTITION BY RANGE (v);
CREATE TABLE s.ctaa_range_part_def_low PARTITION OF s.ctaa_range_part_def FOR VALUES FROM (MINVALUE) TO (0);
CREATE TABLE s.ctaa_range_part_def_high PARTITION OF s.ctaa_range_part_def FOR VALUES FROM (0) TO (MAXVALUE);
CREATE TABLE s.ctaa_range_part_def_def PARTITION OF s.ctaa_range_part_def DEFAULT
